SELECT t1.network, SUM(t1.cnt) AS total_cnt, ROUND(SUM(t1.cnt) * 100.0 / IFNULL(MAX(t2.total_cnt), 1), 2) AS ratio_value FROM t_link_network_stats t1 JOIN ( SELECT SUM(cnt) AS total_cnt FROM t_link_network_stats WHERE full_short_url IN
#{url}
AND date BETWEEN #{start} AND #{end} AND del_flag = 0 AND network != '未知网络' ) t2 WHERE t1.full_short_url IN
#{url}
AND t1.date BETWEEN #{start} AND #{end} AND t1.del_flag = 0 AND t1.network != '未知网络' GROUP BY t1.network ORDER BY total_cnt DESC
